'use strict';

(function() {
  let supabase = window.supabaseClient || (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null);

  function getClient() {
    return window.supabaseClient || (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null);
  }

  function isOnline() {
    if (typeof window !== 'undefined' && window.__ledgio_forceOffline !== undefined) {
      return !window.__ledgio_forceOffline;
    }
    return typeof navigator !== 'undefined' ? navigator.onLine : true;
  }

  function isRealUserIdentity(id) {
    if (!id || typeof id !== 'string') return false;
    const trimmed = id.trim();
    if (!trimmed || trimmed === 'default_user' || trimmed === 'null' || trimmed === 'undefined' || trimmed === 'Guest') {
      return false;
    }
    const isUuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(trimmed);
    if (isUuid) return true;
    const isDevOrTest = typeof window !== 'undefined' && (
      window.__LEDGIO_TEST_MODE__ ||
      window.location.hostname === '127.0.0.1' ||
      window.location.hostname === 'localhost' ||
      window.location.protocol === 'file:'
    );
    if (isDevOrTest && /^[a-zA-Z0-9_\-\.]+$/.test(trimmed)) {
      return true;
    }
    return false;
  }

  function isUuid(id) {
    if (!id || typeof id !== 'string') return false;
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id.trim());
  }

  function withTimeout(promise, ms) {
    const timeoutMs = ms || (typeof window !== 'undefined' && window.__ledgio_authTimeoutMs) || 4000;
    let timer;
    const timeoutPromise = new Promise((_, reject) => {
      timer = setTimeout(() => {
        const timeoutErr = new Error('auth_timeout');
        timeoutErr.isTimeout = true;
        reject(timeoutErr);
      }, timeoutMs);
    });
    return Promise.race([
      Promise.resolve(promise).finally(() => clearTimeout(timer)),
      timeoutPromise
    ]);
  }

  function markAuthReady() {
    if (typeof document !== 'undefined' && document.documentElement) {
      document.documentElement.classList.add('auth-ready');
    }
    if (typeof window !== 'undefined') {
      if (window.__ledgio_authFailSafeTimer) {
        clearTimeout(window.__ledgio_authFailSafeTimer);
        window.__ledgio_authFailSafeTimer = null;
      }
      if (window.__ledgio_oauthFailSafeTimer) {
        clearTimeout(window.__ledgio_oauthFailSafeTimer);
        window.__ledgio_oauthFailSafeTimer = null;
      }
    }
  }

  function isAuthRejection(err) {
    if (!err) return false;
    const msg = (err.message || err.error_description || String(err)).toLowerCase();
    if (msg.includes('auth_timeout')) return false;
    if (msg.includes('auth session missing')) {
      return isOnline();
    }
    const status = err.status || err.statusCode;
    if (status === 400 || status === 401 || status === 403) return true;
    const authPatterns = [
      'invalid refresh token', 'refresh token not found', 'jwt expired',
      'invalid grant', 'session not found', 'user not found', 'token has been revoked'
    ];
    return authPatterns.some(p => msg.includes(p));
  }

  window.logout = async function() {
    console.log('[Ledgio Auth] Checking pending sync queue and local data before logout...');
    const currentUid = localStorage.getItem('sb_user_id');
    let pendingCount = 0;
    const enqueuedIds = new Set();
    if (currentUid && isRealUserIdentity(currentUid)) {
      try {
        const queueKeys = [`ledgio_sync_queue_${currentUid}`];
        queueKeys.forEach(k => {
          const raw = localStorage.getItem(k);
          if (raw) {
            try {
              const queue = JSON.parse(raw);
              if (Array.isArray(queue)) {
                pendingCount += queue.length;
                queue.forEach(item => {
                  if (item && item.data && item.data.id) {
                    enqueuedIds.add(String(item.data.id));
                  }
                });
              }
            } catch (e) {}
          }
        });
      } catch (e) {
        console.warn('Error reading sync queues on logout:', e);
      }

      let localUnsyncedCount = 0;
      try {
        const seenRecordIds = new Set();
        const lastSyncRaw = localStorage.getItem(`ledgio_last_sync_${currentUid}`);
        const lastSyncTime = lastSyncRaw ? new Date(lastSyncRaw).getTime() : 0;

        const userBudgetKeys = [`smartBudgetData_${currentUid}`];
        userBudgetKeys.forEach(k => {
          const raw = localStorage.getItem(k);
          if (raw) {
            try {
              const data = JSON.parse(raw);
              if (data && typeof data === 'object') {
                const collections = ['expenses', 'goals', 'goal_deposits', 'loans', 'loan_settlements', 'income_entries'];
                collections.forEach(col => {
                  if (Array.isArray(data[col])) {
                    data[col].forEach(rec => {
                      if (!rec || typeof rec !== 'object') return;
                      const recId = rec.id ? String(rec.id) : null;
                      if (recId) {
                        if (enqueuedIds.has(recId)) return;
                        if (seenRecordIds.has(recId)) return;
                        seenRecordIds.add(recId);
                      }
                      if (!lastSyncTime || isNaN(lastSyncTime)) {
                        localUnsyncedCount++;
                      } else {
                        const t = rec.updated_at || rec.created_at || rec.date || rec.entry_date;
                        const recTime = t ? new Date(t).getTime() : 0;
                        if (!recTime || isNaN(recTime) || recTime > lastSyncTime) {
                          localUnsyncedCount++;
                        }
                      }
                    });
                  }
                });
              }
            } catch (err) {}
          }
        });

        const userIncomeKey = `ledgio_income_entries_${currentUid}`;
        const rawInc = localStorage.getItem(userIncomeKey);
        if (rawInc) {
          try {
            const entries = JSON.parse(rawInc);
            if (Array.isArray(entries)) {
              entries.forEach(rec => {
                if (!rec || typeof rec !== 'object') return;
                const recId = rec.id ? String(rec.id) : null;
                if (recId) {
                  if (enqueuedIds.has(recId)) return;
                  if (seenRecordIds.has(recId)) return;
                  seenRecordIds.add(recId);
                }
                if (!lastSyncTime || isNaN(lastSyncTime)) {
                  localUnsyncedCount++;
                } else {
                  const t = rec.updated_at || rec.created_at || rec.entry_date;
                  const recTime = t ? new Date(t).getTime() : 0;
                  if (!recTime || isNaN(recTime) || recTime > lastSyncTime) {
                    localUnsyncedCount++;
                  }
                }
              });
            }
          } catch (err) {}
        }
      } catch (e) {
        console.warn('Error checking local financial records on logout:', e);
      }

      const totalUnsynced = pendingCount + localUnsyncedCount;
      if (totalUnsynced > 0) {
        const confirmMsg = `You have ${totalUnsynced} change${totalUnsynced === 1 ? '' : 's'} not yet backed up to the cloud. Log out anyway?`;
        let proceed = true;
        if (typeof window.showConfirm === 'function') {
          proceed = await window.showConfirm(confirmMsg);
        } else {
          proceed = window.confirm(confirmMsg);
        }
        if (!proceed) {
          return false;
        }
      }
    }

    console.log('[Ledgio Auth] Logging out user and clearing local credentials...');
    supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
    if (supabase) {
      try {
        await supabase.auth.signOut();
      } catch (e) {
        console.warn('Error signing out from Supabase:', e);
      }
    }

    try {
      const keysToRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k) continue;
        if (
          k.startsWith('ledgio_stat_views_') ||
          k.startsWith('ledgio_categories_cache_') ||
          k.startsWith('ledgio_categories_migrated_') ||
          k.startsWith('ledgio_announcement_seen_') ||
          k.startsWith('ledgio_reset_epoch_')
        ) {
          continue;
        }
        if (
          k.startsWith('smartBudgetData') ||
          k.startsWith('ledgio_income_entries_') ||
          k.startsWith('ledgio_income_pulled_') ||
          k.startsWith('ledgio_legacy_income_') ||
          k.startsWith('ledgio_sync_queue_') ||
          k.startsWith('ledgio_dead_letter_') ||
          k.startsWith('ledgio_vault_') ||
          k.startsWith('ledgio_safety_backup') ||
          k.startsWith('ledgio_stealth_') ||
          k.startsWith('ledgio_sidebar_collapsed_') ||
          k.startsWith('ledgio_last_sync_') ||
          k.startsWith('ledgio_pending_cloud_reset_') ||
          k.startsWith('sb_') ||
          k.startsWith('sb-')
        ) {
          keysToRemove.push(k);
        }
      }
      keysToRemove.forEach(k => {
        try { localStorage.removeItem(k); } catch (e) {}
      });

      const defaultUserKeys = [
        'smartBudgetData_default_user',
        'ledgio_income_entries_default_user',
        'ledgio_sync_queue_default_user',
        'ledgio_dead_letter_default_user',
        'ledgio_reset_epoch_default_user',
        'ledgio_vault_default_user',
        'ledgio_categories_cache_default_user',
        'ledgio_pending_cloud_reset_default_user',
        'ledgio_last_sync_default_user',
        'smartBudgetData'
      ];
      defaultUserKeys.forEach(k => {
        try { localStorage.removeItem(k); } catch (e) {}
      });
    } catch (err) {
      console.warn('Error purging localStorage on logout:', err);
    }

    sessionStorage.setItem('just_logged_out', 'true');
    handleAuthRedirect('index.html');
    return true;
  };

  function handleAuthRedirect(target) {
    window.__ledgio_lastRedirectTarget = target;
    if (!window.__ledgio_suppressRedirect) {
      window.location.replace(target);
    }
  }

  function navigateToDashboard() {
    if (document.activeElement && typeof document.activeElement.blur === 'function') {
      document.activeElement.blur();
    }
    window.location.replace('dashboard.html');
  }

  async function checkAuth() {
    window.__ledgio_lastRedirectTarget = null;
    const path = window.location.pathname;
    const pageName = (path.replace(/\/+$/, '').split('/').pop() || '').replace(/\.html$/i, '').toLowerCase();
    const isAuthPage = pageName === 'login' || pageName === 'signup';
    const isDashboard = pageName === 'dashboard';
    const isLanding = !isAuthPage && !isDashboard && (
      pageName === 'index' ||
      pageName === '' ||
      pageName === 'ledgio'
    );

    if (sessionStorage.getItem('just_logged_out') === 'true') {
      sessionStorage.removeItem('just_logged_out');
      if (isDashboard) {
        handleAuthRedirect('index.html');
        return false;
      }
    }

    if (isAuthPage) {
      try {
        const params = new URLSearchParams(window.location.search);
        const reason = params.get('reason');
        const alertEl = document.getElementById('login-session-expired-alert');
        if (alertEl && (reason === 'session_expired' || reason === 'oauth_timeout' || reason === 'oauth_error')) {
          const textEl = alertEl.querySelector('span');
          if (textEl && reason === 'oauth_timeout') {
            textEl.textContent = "Sign-in didn't finish. Please try again.";
          } else if (textEl && reason === 'oauth_error') {
            const detail = (params.get('msg') || '').slice(0, 200);
            textEl.textContent = 'Sign-in failed' + (detail ? ': ' + detail.replace(/\.?\s*$/, '.') : '.') + ' Please try again.';
          }
          alertEl.style.display = 'flex';
        }
      } catch (e) {}
    }

    supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
    const verifyStart = (typeof performance !== 'undefined' && typeof performance.now === 'function') ? performance.now() : Date.now();
    window.__ledgio_startupTiming = window.__ledgio_startupTiming || {};

    if (isDashboard) {
      if (!isOnline()) {
        window.__ledgio_authVerificationState = 'offline';
        window.__ledgio_startupTiming.verifyResult = 'offline';
        markAuthReady();
        if (typeof window.updateSyncStatusUI === 'function') {
          window.updateSyncStatusUI();
        }
      } else if (!window.__ledgio_authVerificationState || window.__ledgio_authVerificationState === 'offline') {
        window.__ledgio_authVerificationState = 'pending';
        if (typeof window.updateSyncStatusUI === 'function') {
          window.updateSyncStatusUI();
        }
      }
    }

    if (isDashboard && supabase && typeof supabase.auth?.exchangeCodeForSession === 'function') {
      const authCode = new URLSearchParams(window.location.search).get('code');
      if (authCode) {
        try {
          const { error: exchangeErr } = await withTimeout(supabase.auth.exchangeCodeForSession(authCode), 6000);
          if (exchangeErr) throw exchangeErr;
          try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {}
        } catch (e) {
          const msg = (e && e.message && e.message !== 'auth_timeout') ? e.message : "Sign-in didn't finish";
          handleAuthRedirect('login.html?reason=oauth_error&msg=' + encodeURIComponent(String(msg).slice(0, 200)));
          return false;
        }
      }
    }

    let liveUser = null;
    let getSessionTimedOut = false;
    if (supabase && typeof supabase.auth?.getSession === 'function') {
      try {
        const { data: sessionData } = await withTimeout(supabase.auth.getSession(), 4000);
        if (sessionData?.session?.user && isRealUserIdentity(sessionData.session.user.id)) {
          liveUser = sessionData.session.user;
        }
      } catch (e) {
        if (e && (e.message === 'auth_timeout' || e.isTimeout)) {
          getSessionTimedOut = true;
          if (typeof window !== 'undefined') window.__ledgio_authTimedOut = true;
        }
        console.warn('[Ledgio Auth] Supabase getSession check (timeout or error):', e);
      }
    }

    if (liveUser) {
      if (typeof window !== 'undefined') {
        window.__ledgio_authTimedOut = false;
        window.__ledgio_authVerificationState = 'verified';
        window.__ledgio_startupTiming.verifyMs = Math.round(((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - verifyStart);
        window.__ledgio_startupTiming.verifyResult = 'verified';
      }
      sessionStorage.removeItem('just_logged_out');
      localStorage.setItem('sb_auth', 'true');
      localStorage.setItem('sb_user_id', liveUser.id);
      const metaName = liveUser.user_metadata?.full_name || liveUser.user_metadata?.name;
      const emailPrefix = liveUser.email ? liveUser.email.split('@')[0] : 'User';
      const fullName = metaName || (emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1));
      localStorage.setItem('sb_username', fullName);

      if (isAuthPage || isLanding) {
        console.log('[Ledgio Auth] Active verified session. Redirecting to dashboard...');
        navigateToDashboard();
        return true;
      }

      if (isDashboard) {
        markAuthReady();
        if (typeof window.updateSyncStatusUI === 'function') {
          window.updateSyncStatusUI();
        }
        return true;
      }
      return true;
    }

    if (isAuthPage) {
      return false;
    }

    const cachedUid = localStorage.getItem('sb_user_id');
    const hasValidCachedAuth = localStorage.getItem('sb_auth') === 'true' && isRealUserIdentity(cachedUid);

    if (isDashboard) {
      if (hasValidCachedAuth) {
        if (!isOnline()) {
          console.log('[Ledgio Auth] Operating in offline mode for cached user:', cachedUid);
          if (typeof window !== 'undefined') {
            window.__ledgio_authTimedOut = true;
            window.__ledgio_authVerificationState = 'offline';
            window.__ledgio_startupTiming.verifyResult = 'offline';
          }
          markAuthReady();
          if (typeof window !== 'undefined' && typeof window.updateSyncStatusUI === 'function') {
            window.updateSyncStatusUI();
          }
          return true;
        }

        if (isUuid(cachedUid)) {
          const activeAuth = supabase?.auth || window.supabaseClient?.auth || (window.getSupabaseClient ? window.getSupabaseClient()?.auth : null);
          if (activeAuth && typeof activeAuth.refreshSession === 'function') {
            try {
              const { data: refreshData, error: refreshErr } = await withTimeout(activeAuth.refreshSession(), 4000);
              if (refreshData?.session?.user && isRealUserIdentity(refreshData.session.user.id)) {
                if (typeof window !== 'undefined') {
                  window.__ledgio_authTimedOut = false;
                  window.__ledgio_authVerificationState = 'verified';
                  window.__ledgio_startupTiming.verifyMs = Math.round(((typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now()) - verifyStart);
                  window.__ledgio_startupTiming.verifyResult = 'refreshed';
                }
                sessionStorage.removeItem('just_logged_out');
                localStorage.setItem('sb_auth', 'true');
                localStorage.setItem('sb_user_id', refreshData.session.user.id);
                const metaName = refreshData.session.user.user_metadata?.full_name || refreshData.session.user.user_metadata?.name;
                const emailPrefix = refreshData.session.user.email ? refreshData.session.user.email.split('@')[0] : 'User';
                const fullName = metaName || (emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1));
                localStorage.setItem('sb_username', fullName);
                markAuthReady();
                if (typeof window.updateSyncStatusUI === 'function') {
                  window.updateSyncStatusUI();
                }
                return true;
              }

              if (refreshErr && isAuthRejection(refreshErr)) {
                console.warn('[Ledgio Auth] Session refresh rejected:', refreshErr.message);
                if (typeof window !== 'undefined') {
                  window.__ledgio_authVerificationState = 'rejected';
                  window.__ledgio_startupTiming.verifyResult = 'rejected';
                }
                localStorage.removeItem('sb_auth');
                handleAuthRedirect('login.html?reason=session_expired');
                return false;
              }

              console.log('[Ledgio Auth] Session recovery deferred (service unavailable). Continuing for:', cachedUid);
              if (typeof window !== 'undefined') {
                window.__ledgio_authVerificationState = isOnline() ? 'reconnecting' : 'offline';
                window.__ledgio_startupTiming.verifyResult = 'timeout';
              }
              markAuthReady();
              if (typeof window !== 'undefined' && typeof window.updateSyncStatusUI === 'function') {
                window.updateSyncStatusUI();
              }
              return true;
            } catch (err) {
              if (isAuthRejection(err)) {
                console.warn('[Ledgio Auth] Session refresh error rejected:', err.message);
                if (typeof window !== 'undefined') {
                  window.__ledgio_authVerificationState = 'rejected';
                  window.__ledgio_startupTiming.verifyResult = 'rejected';
                }
                localStorage.removeItem('sb_auth');
                handleAuthRedirect('login.html?reason=session_expired');
                return false;
              }
              if (typeof window !== 'undefined') {
                window.__ledgio_authVerificationState = isOnline() ? 'reconnecting' : 'offline';
                window.__ledgio_startupTiming.verifyResult = 'timeout';
              }
              markAuthReady();
              if (typeof window !== 'undefined' && typeof window.updateSyncStatusUI === 'function') {
                window.updateSyncStatusUI();
              }
              return true;
            }
          } else {
            if (typeof window !== 'undefined') {
              window.__ledgio_authVerificationState = isOnline() ? 'reconnecting' : 'offline';
              window.__ledgio_startupTiming.verifyResult = 'unverified';
            }
            markAuthReady();
            if (typeof window !== 'undefined' && typeof window.updateSyncStatusUI === 'function') {
              window.updateSyncStatusUI();
            }
            return true;
          }
        } else {
          if (typeof window !== 'undefined') {
            window.__ledgio_authVerificationState = 'verified';
            window.__ledgio_startupTiming.verifyResult = 'verified';
          }
          markAuthReady();
          if (typeof window !== 'undefined' && typeof window.updateSyncStatusUI === 'function') {
            window.updateSyncStatusUI();
          }
          return true;
        }
      }

      console.log('[Ledgio Auth] No live session and no cached real-user identity. Redirecting to landing page...');
      handleAuthRedirect('index.html');
      return false;
    }

    if (isLanding && hasValidCachedAuth) {
      document.querySelectorAll('.nav-login-btn, .btn-mobile-login').forEach(el => {
        el.href = 'dashboard.html';
        el.textContent = 'Dashboard';
      });
      document.querySelectorAll('.nav-signup-btn, .btn-mobile-signup, .hero-cta-group a[href="signup.html"], .cta-banner-3d a[href="signup.html"]').forEach(el => {
        el.href = 'dashboard.html';
        el.textContent = 'Open Dashboard';
      });
    }

    return false;
  }

  supabase = getClient();
  if (supabase && supabase.auth && typeof supabase.auth.onAuthStateChange === 'function') {
    supabase.auth.onAuthStateChange((event, session) => {
      if ((event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'USER_UPDATED') && session?.user && isRealUserIdentity(session.user.id)) {
        sessionStorage.removeItem('just_logged_out');
        localStorage.setItem('sb_auth', 'true');
        localStorage.setItem('sb_user_id', session.user.id);
        const metaName = session.user.user_metadata?.full_name || session.user.user_metadata?.name;
        const emailPrefix = session.user.email ? session.user.email.split('@')[0] : 'User';
        const fullName = metaName || (emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1));
        localStorage.setItem('sb_username', fullName);
        if (window.__ledgio_isOAuthCallback) {
          window.__ledgio_isOAuthCallback = false;
          markAuthReady();
          try { window.history.replaceState(null, '', window.location.pathname); } catch (e) {}
          if (typeof window.updateSyncStatusUI === 'function') {
            window.updateSyncStatusUI();
          }
        }
      } else if (event === 'SIGNED_OUT') {
        if (sessionStorage.getItem('just_logged_out') === 'true') {
          localStorage.removeItem('sb_auth');
          localStorage.removeItem('sb_user_id');
          localStorage.removeItem('sb_username');
        }
      }
    });
  }

  window.__ledgio_checkAuth = checkAuth;
  window.__ledgio_checkAuthPromise = checkAuth();

  function showError(id, message) {
    const el = document.getElementById(id + '-error');
    if (el) {
      el.textContent = message;
      el.style.display = 'block';
    }
  }

  function clearError(id) {
    const el = document.getElementById(id + '-error');
    if (el) {
      el.textContent = '';
      el.style.display = 'none';
    }
  }

  function isValidEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  document.addEventListener('DOMContentLoaded', () => {
    const loginForm = document.getElementById('login-form');
    const signupForm = document.getElementById('signup-form');

    const toggleBtns = document.querySelectorAll('.toggle-password-btn');
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        const wrapper = this.closest('.input-icon-wrapper');
        const input = wrapper ? wrapper.querySelector('input') : null;
        const icon = this.querySelector('i');

        if (input && input.type === 'password') {
          input.type = 'text';
          if (icon) {
            icon.classList.remove('fa-eye');
            icon.classList.add('fa-eye-slash');
          }
        } else if (input) {
          input.type = 'password';
          if (icon) {
            icon.classList.remove('fa-eye-slash');
            icon.classList.add('fa-eye');
          }
        }
      });
    });

    const signupPass = document.querySelector('#signup-form #password');
    const strengthFill = document.getElementById('strength-fill');

    if (signupPass && strengthFill) {
      signupPass.addEventListener('input', (e) => {
        const val = e.target.value;
        let score = 0;

        if (val.length >= 8) score += 25;
        if (/[A-Z]/.test(val)) score += 25;
        if (/[0-9]/.test(val)) score += 25;
        if (/[^A-Za-z0-9]/.test(val)) score += 25;

        strengthFill.style.width = score + '%';

        if (score <= 25) {
          strengthFill.style.backgroundColor = '#f43f5e';
        } else if (score <= 50) {
          strengthFill.style.backgroundColor = '#f97316';
        } else if (score <= 75) {
          strengthFill.style.backgroundColor = '#f59e0b';
        } else {
          strengthFill.style.backgroundColor = '#10b981';
        }
      });
    }

    if (loginForm) {
      const emailInput = loginForm.querySelector('#email');
      const passInput = loginForm.querySelector('#password');

      emailInput?.addEventListener('input', () => clearError('email'));
      passInput?.addEventListener('input', () => clearError('password'));

      loginForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        if (document.activeElement && typeof document.activeElement.blur === 'function') {
          document.activeElement.blur();
        }
        let valid = true;

        if (!emailInput.value.trim() || !isValidEmail(emailInput.value)) {
          showError('email', 'Please enter a valid email address.');
          valid = false;
        }

        if (!passInput.value || passInput.value.length < 6) {
          showError('password', 'Password must be at least 6 characters.');
          valid = false;
        }

        if (!valid) return;

        const btn = loginForm.querySelector('button[type="submit"]');
        const textSpan = btn.querySelector('.btn-text');
        const loadingSpan = btn.querySelector('.btn-loading');

        if (textSpan) textSpan.style.display = 'none';
        if (loadingSpan) loadingSpan.style.display = 'inline-flex';
        btn.disabled = true;

        try {
          supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
          if (supabase) {
            const { data, error } = await supabase.auth.signInWithPassword({
              email: emailInput.value.trim(),
              password: passInput.value
            });

            if (error) {
              showError('password', error.message || 'Invalid email or password.');
              return;
            }

            if (data?.session) {
              sessionStorage.removeItem('just_logged_out');
              localStorage.setItem('sb_auth', 'true');
              const userMetaName = data.user?.user_metadata?.full_name || data.user?.user_metadata?.name;
              const emailPrefix = data.user?.email ? data.user.email.split('@')[0] : 'User';
              const fullName = userMetaName || (emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1));
              localStorage.setItem('sb_username', fullName);
              localStorage.setItem('sb_user_id', data.user.id);
              try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
              navigateToDashboard();
            }
          } else {
            sessionStorage.removeItem('just_logged_out');
            localStorage.setItem('sb_auth', 'true');
            const emailPrefix = emailInput.value.trim().split('@')[0] || 'User';
            const fullName = emailPrefix.charAt(0).toUpperCase() + emailPrefix.slice(1);
            localStorage.setItem('sb_username', fullName);
            localStorage.setItem('sb_user_id', 'local_' + emailInput.value.trim().toLowerCase());
            try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
            navigateToDashboard();
          }
        } catch (err) {
          showError('password', 'Authentication failed. Please try again.');
        } finally {
          if (textSpan) textSpan.style.display = 'inline-flex';
          if (loadingSpan) loadingSpan.style.display = 'none';
          btn.disabled = false;
        }
      });
    }

    if (signupForm) {
      const firstInput = signupForm.querySelector('#first-name');
      const lastInput = signupForm.querySelector('#last-name');
      const emailInput = signupForm.querySelector('#email');
      const passInput = signupForm.querySelector('#password');
      const confirmInput = signupForm.querySelector('#confirm-password');
      const termsBox = signupForm.querySelector('#terms');

      firstInput?.addEventListener('input', () => clearError('firstName'));
      lastInput?.addEventListener('input', () => clearError('lastName'));
      emailInput?.addEventListener('input', () => clearError('email'));
      passInput?.addEventListener('input', () => clearError('password'));
      confirmInput?.addEventListener('input', () => clearError('confirmPassword'));
      termsBox?.addEventListener('change', () => clearError('terms'));

      signupForm.addEventListener('submit', async (e) => {
        e.preventDefault();
        if (document.activeElement && typeof document.activeElement.blur === 'function') {
          document.activeElement.blur();
        }
        let valid = true;

        if (!firstInput.value.trim()) {
          showError('firstName', 'First name is required');
          valid = false;
        }

        if (!lastInput.value.trim()) {
          showError('lastName', 'Last name is required');
          valid = false;
        }

        if (!emailInput.value.trim() || !isValidEmail(emailInput.value)) {
          showError('email', 'Please enter a valid email address');
          valid = false;
        }

        if (!passInput.value || passInput.value.length < 6) {
          showError('password', 'Password must be at least 6 characters');
          valid = false;
        }

        if (passInput.value !== confirmInput.value) {
          showError('confirmPassword', 'Passwords do not match');
          valid = false;
        }

        if (!termsBox.checked) {
          showError('terms', 'You must agree to the Terms of Service');
          valid = false;
        }

        if (!valid) return;

        const btn = signupForm.querySelector('button[type="submit"]');
        const textSpan = btn.querySelector('.btn-text');
        const loadingSpan = btn.querySelector('.btn-loading');

        if (textSpan) textSpan.style.display = 'none';
        if (loadingSpan) loadingSpan.style.display = 'inline-flex';
        btn.disabled = true;

        try {
          const fullName = `${firstInput.value.trim()} ${lastInput.value.trim()}`;

          supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
          if (supabase) {
            const { data, error } = await supabase.auth.signUp({
              email: emailInput.value.trim(),
              password: passInput.value,
              options: {
                data: {
                  full_name: fullName
                }
              }
            });

            if (error) {
              showError('email', error.message || 'Signup failed.');
              return;
            }

            if (data?.user) {
              sessionStorage.removeItem('just_logged_out');
              localStorage.setItem('sb_auth', 'true');
              localStorage.setItem('sb_username', fullName);
              localStorage.setItem('sb_user_id', data.user.id);
              try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
              navigateToDashboard();
            }
          } else {
            sessionStorage.removeItem('just_logged_out');
            localStorage.setItem('sb_auth', 'true');
            localStorage.setItem('sb_username', fullName);
            localStorage.setItem('sb_user_id', 'local_' + emailInput.value.trim().toLowerCase());
            try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
            navigateToDashboard();
          }
        } catch (err) {
          showError('email', 'An error occurred during signup.');
        } finally {
          if (textSpan) textSpan.style.display = 'inline-flex';
          if (loadingSpan) loadingSpan.style.display = 'none';
          btn.disabled = false;
        }
      });
    }

    const googleBtns = document.querySelectorAll('#google-login, #google-signup');
    googleBtns.forEach(btn => {
      btn.addEventListener('click', async () => {
        if (document.activeElement && typeof document.activeElement.blur === 'function') {
          document.activeElement.blur();
        }
        supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
        if (supabase) {
          const redirectTo = new URL('dashboard.html', window.location.href).href;
          await supabase.auth.signInWithOAuth({
            provider: 'google',
            options: { redirectTo }
          });
        } else {
          sessionStorage.removeItem('just_logged_out');
          localStorage.setItem('sb_auth', 'true');
          localStorage.setItem('sb_username', 'Google User');
          localStorage.setItem('sb_user_id', 'local_google');
          try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
          navigateToDashboard();
        }
      });
    });

    const githubBtns = document.querySelectorAll('#github-login, #github-signup');
    githubBtns.forEach(btn => {
      btn.addEventListener('click', async () => {
        if (document.activeElement && typeof document.activeElement.blur === 'function') {
          document.activeElement.blur();
        }
        supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
        if (supabase) {
          const redirectTo = new URL('dashboard.html', window.location.href).href;
          await supabase.auth.signInWithOAuth({
            provider: 'github',
            options: { redirectTo }
          });
        } else {
          sessionStorage.removeItem('just_logged_out');
          localStorage.setItem('sb_auth', 'true');
          localStorage.setItem('sb_username', 'GitHub User');
          localStorage.setItem('sb_user_id', 'local_github');
          try { localStorage.removeItem('smartBudgetData'); } catch (e) {}
          navigateToDashboard();
        }
      });
    });

    const forgotTrigger = document.getElementById('forgot-password-trigger');
    const backToLoginBtn = document.getElementById('back-to-login-btn');
    const forgotView = document.getElementById('forgot-password-view');
    const loginHeaderBlock = document.querySelector('.auth-form-container > .auth-header-block');
    const loginFormEl = document.getElementById('login-form');
    const authDivider = document.querySelector('.auth-divider-modern');
    const socialAuthGrid = document.querySelector('.social-auth-grid');
    const signupRedirect = document.querySelector('.auth-form-container > p');
    const resetForm = document.getElementById('forgot-password-form');
    const resetEmailInput = document.getElementById('reset-email');
    const resetStatusMsg = document.getElementById('reset-status-message');

    if (forgotTrigger && forgotView) {
      forgotTrigger.addEventListener('click', (e) => {
        e.preventDefault();
        if (loginHeaderBlock) loginHeaderBlock.style.display = 'none';
        if (loginFormEl) loginFormEl.style.display = 'none';
        if (authDivider) authDivider.style.display = 'none';
        if (socialAuthGrid) socialAuthGrid.style.display = 'none';
        if (signupRedirect) signupRedirect.style.display = 'none';

        forgotView.style.display = 'block';
        const currentEmail = document.getElementById('email')?.value?.trim();
        if (currentEmail && resetEmailInput) {
          resetEmailInput.value = currentEmail;
        }
        if (resetStatusMsg) resetStatusMsg.style.display = 'none';
        resetEmailInput?.focus();
      });

      backToLoginBtn?.addEventListener('click', (e) => {
        e.preventDefault();
        forgotView.style.display = 'none';
        if (loginHeaderBlock) loginHeaderBlock.style.display = '';
        if (loginFormEl) loginFormEl.style.display = '';
        if (authDivider) authDivider.style.display = '';
        if (socialAuthGrid) socialAuthGrid.style.display = '';
        if (signupRedirect) signupRedirect.style.display = '';
      });

      resetForm?.addEventListener('submit', async (e) => {
        e.preventDefault();
        const emailVal = resetEmailInput?.value?.trim();
        clearError('reset-email');

        if (!emailVal || !isValidEmail(emailVal)) {
          showError('reset-email', 'Please enter a valid email address.');
          return;
        }

        const btn = document.getElementById('reset-submit-btn');
        const textSpan = btn?.querySelector('.btn-text');
        const loadSpan = btn?.querySelector('.btn-loading');
        if (textSpan) textSpan.style.display = 'none';
        if (loadSpan) loadSpan.style.display = 'inline-flex';
        if (btn) btn.disabled = true;

        try {
          supabase = (typeof window.getSupabaseClient === 'function' ? window.getSupabaseClient() : null) || window.supabaseClient || getClient();
          const redirectTo = new URL('reset-password.html', window.location.href).href;
          if (supabase) {
            await supabase.auth.resetPasswordForEmail(emailVal, { redirectTo });
          }
          if (resetStatusMsg) {
            resetStatusMsg.style.display = 'block';
            resetStatusMsg.style.background = 'rgba(16, 185, 129, 0.12)';
            resetStatusMsg.style.color = '#10b981';
            resetStatusMsg.style.border = '1px solid rgba(16, 185, 129, 0.28)';
            resetStatusMsg.textContent = 'If an account exists for this email, a password reset link has been sent. Please check your inbox and spam folder.';
          }
        } catch (err) {
          if (resetStatusMsg) {
            resetStatusMsg.style.display = 'block';
            resetStatusMsg.style.background = 'rgba(239, 68, 68, 0.12)';
            resetStatusMsg.style.color = '#f87171';
            resetStatusMsg.style.border = '1px solid rgba(239, 68, 68, 0.28)';
            resetStatusMsg.textContent = err.message || 'Unable to send password reset link right now. Please try again.';
          }
        } finally {
          if (textSpan) textSpan.style.display = '';
          if (loadSpan) loadSpan.style.display = 'none';
          if (btn) btn.disabled = false;
        }
      });
    }
  });

})();
